result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/hyphen.py", "content": """"Mini Knuth-Liang style hyphenation engine with an inline pattern set.

Patterns are strings where digits mark break weights between letters,
e.g. '1na', 'n2at', 'hen5at'. Algorithm (implemented exactly):

  1. Surround the lowercase word with '.' on both ends.
  2. Slide every pattern over it, recording the MAX digit seen between
     each pair of adjacent letters.
  3. Allow a hyphen wherever the final value is ODD.
  4. Never place a hyphen within 2 letters of either word edge.
"""

PATTERNS = [
    '1na', 'n2at', '1tion', '2io', 'h1yph', 'hy3ph', 'he2n',
    'hena4', 'hen5at', '1cy', '1de', 'de1co', '4m1p', 'com1',
    'co1m', 'pu2t', '5pute', 'put3er', 'edu1', '1ca', 'ca1t',
]


def _compiled(pattern):
    """Split a pattern into its letters and {gap_offset: digit} map."""
    letters = []
    digits = {}  # gap offset relative to pattern start -> weight
    for ch in pattern:
        if ch.isdigit():
            digits[len(letters)] = int(ch)
        else:
            letters.append(ch)
    return ''.join(letters), digits


_COMPILED = [_compiled(p) for p in PATTERNS]


def hyphenate(word):
    """Return `word` with '-' inserted at allowed break points."""
    w = word.lower()
    if len(w) < 5:
        return word

    text = '.' + w + '.'
    n = len(text)
    vals = [0] * (n + 1)

    for s, digits in _COMPILED:
        start = 0
        while True:
            i = text.find(s, start)
            if i == -1:
                break
            for off, d in digits.items():
                if d > vals[i + off]:
                    vals[i + off] = d
            start = i + 1

    out = []
    for k, ch in enumerate(w):
        out.append(ch)
        # A hyphen after letter k sits at text gap k+1; it must not be
        # within 2 letters of either edge (positions 2 .. len-2).
        if 2 <= k + 1 <= len(w) - 2 and vals[k + 1] % 2 == 1:
            out.append('-')
    return ''.join(out)


if __name__ == '__main__':
    for word in ('hyphenation', 'computer'):
        print(f'{word:>12} -> {hyphenate(word)}')
